            assert_eq!(serde_json::from_str::<FestivalKind>(&json).unwrap(), member);
            assert_eq!(<FestivalKind as Catalogued>::mark(member), member.mark());
            assert_ne!(member.doc(), "");
            assert_ne!(member.glyph(), Some(""));
            let _ = (member.deprecated(), member.sources(), member.unverified());
